def structure_assumptions(tip, mass):
    """🏗️ The load-path texts with the numbers of the build (masses and the tipping case)."""
    m_c = mass["carcass"][0]
    m_f = mass["flap-1"][0]
    total = m_c + sum(mass[f"flap-{i}"][0] for i in (1, 2, 3))
    net = tip["overturningNm"] - tip["restoringNm"]
    return [
        t(f"Masses from section x density of the 1:50 solids: carcass with back and bracket {m_c:.2f} kg, each flap with tray, cheeks, handle and 0.10 kg of plastic pivot fittings {m_f:.2f} kg, cabinet {total:.2f} kg; the folded blanket (1.2 kg) carries no mass in the rig.", f"Massen aus Querschnitt x Dichte der 1:50-Körper: Korpus mit Rückwand und Winkel {m_c:.2f} kg, jede Klappe mit Fachboden, Wangen, Griff und 0,10 kg Kunststoff-Drehbeschlägen {m_f:.2f} kg, Schrank {total:.2f} kg; die gefaltete Decke (1,2 kg) trägt im Skelett keine Masse."),
        t("Stored: the side panels stand on the blanket, which carries the cabinet to the floor (two contact halves). Carried: four hands under the side panels near both ends (contacts with friction 0.6). In use: the side panels stand on the floor (two 151 x 16 mm contacts) and the remaining right bracket restrains the top horizontally (roller at the wall); the left one was torn out.", "Gelagert: die Seitenwände stehen auf der Decke, die den Schrank auf den Boden abträgt (zwei Kontakthälften). Getragen: vier Hände unter den Seitenwänden nahe beiden Enden (Kontakte mit Reibung 0,6). In Gebrauch: die Seitenwände stehen auf dem Boden (zwei Kontakte 151 x 16 mm) und der verbliebene rechte Winkel hält den Deckel waagrecht (Rollenlager an der Wand); der linke ist ausgerissen."),
        t(f"Tipping (EN 14749, ISO 7171, all flaps open at 40 degrees, four pairs of 0.8 kg in each tray): about the front edge of the side panels the carcass restores {tip['restoringNm']:.1f} N m, the open flaps and shoes overturn {tip['overturningNm']:.1f} N m, so without wall fixing the cabinet tips forward by {net:.1f} N m; the bracket at 1.465 m takes about {tip['wallForceN']:.0f} N. With the flaps shut they add {-tip['closedFlapsNm']:.1f} N m of restoring moment and it stands free.", f"Kippen (EN 14749, ISO 7171, alle Klappen bei 40 Grad offen, vier Paar zu 0,8 kg in jedem Fach): um die Vorderkante der Seitenwände richtet der Korpus mit {tip['restoringNm']:.1f} N m auf, die offenen Klappen und Schuhe kippen mit {tip['overturningNm']:.1f} N m, ohne Wandbefestigung kippt der Schrank also mit {net:.1f} N m nach vorn; der Winkel auf 1,465 m nimmt etwa {tip['wallForceN']:.0f} N auf. Mit geschlossenen Klappen tragen diese {-tip['closedFlapsNm']:.1f} N m zum Aufrichten bei und er steht frei."),
        t("Flaps are 16 mm chipboard plates (796 x 16 mm, I = 2.72e-7 m4, P2 1600 MPa, 11 MPa) hinged at the front-bottom edge; their trays and cheeks carry the shoes to the plate and the pivots. The carcass is a rigid box braced by the nailed HDF back; joint loosening of the old cam fittings is not modelled.", "Klappen sind 16-mm-Spanplatten (796 x 16 mm, I = 2,72e-7 m4, P2 1600 MPa, 11 MPa), an der vorderen Unterkante gelagert; Fachboden und Wangen tragen die Schuhe zur Platte und zu den Drehpunkten. Der Korpus ist ein steifer Kasten, ausgesteift durch die genagelte HDF-Rückwand; das Lockern der alten Exzenterverbinder ist nicht modelliert."),
    ]


